 "harness_finding": {
  "bug": "First replay run produced 3 false mismatches (PRs 125/143/390, recorded EXTRACT vs replay SUPERSEDE): the reconstruction omitted user={login}, and minesweeper_rules.is_bot_author only falls back to the author field when user is NOT a dict — an empty/absent user silently disables bot detection. All 3 PRs are google-labs-jules[bot] with changed_files > 40 (minesweeper EXTRACT).",
  "fix": "prlane_replay.reconstruct now sets user={login: author}, mirroring production build_pr_dict. Lesson recorded: replay reconstructions must mirror the producer's dict shape exactly, including nested fields with fallback traps."
 },
 "consequences": {
  "phase_1_unblocked": true,
  "known_gap_class": "recorded NEED_EVIDENCE + replay CANDIDATE + gates pass + not draft = dropped-field NE (base or mergeable_state); identifiable in every later phase, never counted as a tuning effect.",
  "ask_to_steward": "pr-lane-feed v1.1: carry base.ref and mergeable_state per row — with those two fields the replay becomes exact and the gap class disappears."
 }
}

